{
  "story": "During text generation, each new token requires attending to all prior tokens. Without caching, past key and value vectors are recomputed for every step. KV caching stores these vectors in memory, eliminating redundant computations and accelerating decoding speed dramatically.",
  "aha": {
    "stateId": "step_cache_hit",
    "observation": "Notice how storing computed key and value tensors avoids re-running self-attention over the prompt tokens at every single generation step."
  },
  "layout": {
    "preset": "stepper-card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.step_index",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "text": "state.sentence"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.short"
      }
    },
    {
      "id": "readouts",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.step_index"
      }
    }
  ],
  "controls": [
    {
      "id": "step_index",
      "kind": "index",
      "label": "Inference Step",
      "options": [
        "Prompt",
        "Token 1",
        "Token 2",
        "Cache Hit"
      ]
    },
    {
      "id": "reset_btn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "KV Caching Sequence",
        "regions": [
          {
            "id": "prompt_block",
            "label": "Input Prompt",
            "values": ["The", "quick", "brown"]
          },
          {
            "id": "kv_cache",
            "label": "KV Cache Storage",
            "values": ["K_0", "V_0", "K_1", "V_1"]
          },
          {
            "id": "attention_layer",
            "label": "Self-Attention Compute",
            "values": ["MatMul", "Softmax", "Scale"]
          }
        ],
        "states": [
          {
            "id": "step_prompt",
            "label": "1. Prompt",
            "short": "Initial pass",
            "sentence": "The full prompt is processed to compute initial keys and values.",
            "why": "Establishes baseline tensor dimensions for all prompt tokens.",
            "active": ["prompt_block", "attention_layer"],
            "calloutRegion": "prompt_block",
            "readouts": [
              {
                "id": "flops",
                "label": "FLOPs per token",
                "value": "O(N^2)"
              },
              {
                "id": "latency",
                "label": "Latency",
                "value": "45ms"
              }
            ]
          },
          {
            "id": "step_token1",
            "label": "2. Token 1",
            "short": "First generated token",
            "sentence": "Token 1 attends to stored prompt keys and values instead of recomputing them.",
            "why": "Avoids redundant computation for historical tokens.",
            "active": ["kv_cache", "attention_layer"],
            "calloutRegion": "kv_cache",
            "readouts": [
              {
                "id": "flops",
                "label": "FLOPs per token",
                "value": "O(N)"
              },
              {
                "id": "latency",
                "label": "Latency",
                "value": "12ms"
              }
            ]
          },
          {
            "id": "step_token2",
            "label": "3. Token 2",
            "short": "Second generated token",
            "sentence": "Token 2 appends its own K and V vectors to the cache storage.",
            "why": "Grows the cache incrementally for subsequent generation steps.",
            "active": ["kv_cache", "attention_layer"],
            "calloutRegion": "kv_cache",
            "readouts": [
              {
                "id": "flops",
                "label": "FLOPs per token",
                "value": "O(N)"
              },
              {
                "id": "latency",
                "label": "Latency",
                "value": "12ms"
              }
            ]
          },
          {
            "id": "step_cache_hit",
            "label": "4. Cache Hit",
            "short": "Maximized speedup",
            "sentence": "Memory bandwidth replaces heavy compute, yielding constant per-token time.",
            "why": "Proves that attention complexity drops from quadratic to linear relative to generation length.",
            "active": ["kv_cache"],
            "calloutRegion": "kv_cache",
            "readouts": [
              {
                "id": "flops",
                "label": "FLOPs per token",
                "value": "O(N)"
              },
              {
                "id": "latency",
                "label": "Latency",
                "value": "11ms"
              }
            ]
          }
        ]
      }
    ]
  }
}
